00129 void SampleAdaptiveOffset::create( int picWidth, int picHeight, ChromaFormat format, uint32_t maxCUWidth, uint32_t maxCUHeight, uint32_t maxCUDepth, uint32_t lumaBitShift, uint32_t chromaBitShift )
00130 {
00131   //temporary picture buffer
00132   UnitArea picArea(format, Area(0, 0, picWidth, picHeight));
00133 
00134   m_tempBuf.destroy();
00135   m_tempBuf.create( picArea );
00136 
00137   //bit-depth related
00138   for(int compIdx = 0; compIdx < MAX_NUM_COMPONENT; compIdx++)
00139   {
00140     m_offsetStepLog2  [compIdx] = isLuma(ComponentID(compIdx))? lumaBitShift : chromaBitShift;
00141   }
00142   m_numberOfComponents = getNumberValidComponents(format);
00143 }
