00150 void SampleAdaptiveOffset::invertQuantOffsets(ComponentID compIdx, int typeIdc, int typeAuxInfo, int* dstOffsets, int* srcOffsets)
00151 {
00152   int codedOffset[MAX_NUM_SAO_CLASSES];
00153 
00154   ::memcpy(codedOffset, srcOffsets, sizeof(int)*MAX_NUM_SAO_CLASSES);
00155   ::memset(dstOffsets, 0, sizeof(int)*MAX_NUM_SAO_CLASSES);
00156 
00157   if(typeIdc == SAO_TYPE_START_BO)
00158   {
00159     for(int i=0; i< 4; i++)
00160     {
00161       dstOffsets[(typeAuxInfo+ i)%NUM_SAO_BO_CLASSES] = codedOffset[(typeAuxInfo+ i)%NUM_SAO_BO_CLASSES]*(1<<m_offsetStepLog2[compIdx]);
00162     }
00163   }
00164   else //EO
00165   {
00166     for(int i=0; i< NUM_SAO_EO_CLASSES; i++)
00167     {
00168       dstOffsets[i] = codedOffset[i] *(1<<m_offsetStepLog2[compIdx]);
00169     }
00170     CHECK(dstOffsets[SAO_CLASS_EO_PLAIN] != 0, "EO offset is not '0'"); //keep EO plain offset as zero
00171   }
00172 
00173 }
