00175 int SampleAdaptiveOffset::getMergeList(CodingStructure& cs, int ctuRsAddr, SAOBlkParam* blkParams, SAOBlkParam* mergeList[NUM_SAO_MERGE_TYPES])
00176 {
00177   const PreCalcValues& pcv = *cs.pcv;
00178 
00179   int ctuX = ctuRsAddr % pcv.widthInCtus;
00180   int ctuY = ctuRsAddr / pcv.widthInCtus;
00181   const CodingUnit& cu = *cs.getCU(Position(ctuX*pcv.maxCUWidth, ctuY*pcv.maxCUHeight), CH_L);
00182   int mergedCTUPos;
00183   int numValidMergeCandidates = 0;
00184 
00185   for(int mergeType=0; mergeType< NUM_SAO_MERGE_TYPES; mergeType++)
00186   {
00187     SAOBlkParam* mergeCandidate = NULL;
00188 
00189     switch(mergeType)
00190     {
00191     case SAO_MERGE_ABOVE:
00192       {
00193         if(ctuY > 0)
00194         {
00195           mergedCTUPos = ctuRsAddr- pcv.widthInCtus;
00196           if(cs.getCURestricted(Position(ctuX*pcv.maxCUWidth, (ctuY-1)*pcv.maxCUHeight), cu, cu.chType))
00197           {
00198             mergeCandidate = &(blkParams[mergedCTUPos]);
00199           }
00200         }
00201       }
00202       break;
00203     case SAO_MERGE_LEFT:
00204       {
00205         if(ctuX > 0)
00206         {
00207           mergedCTUPos = ctuRsAddr- 1;
00208           if(cs.getCURestricted(Position((ctuX-1)*pcv.maxCUWidth, ctuY*pcv.maxCUHeight), cu, cu.chType))
00209           {
00210             mergeCandidate = &(blkParams[mergedCTUPos]);
00211           }
00212         }
00213       }
00214       break;
00215     default:
00216       {
00217         THROW("not a supported merge type");
00218       }
00219     }
00220 
00221     mergeList[mergeType]=mergeCandidate;
00222     if (mergeCandidate != NULL)
00223     {
00224       numValidMergeCandidates++;
00225     }
00226   }
00227 
00228   return numValidMergeCandidates;
00229 }
00230 
00231 
00232 void SampleAdaptiveOffset::reconstructBlkSAOParam(SAOBlkParam& recParam, SAOBlkParam* mergeList[NUM_SAO_MERGE_TYPES])
00233 {
00234   const int numberOfComponents = m_numberOfComponents;
00235   for(int compIdx = 0; compIdx < numberOfComponents; compIdx++)
00236   {
00237     const ComponentID component = ComponentID(compIdx);
00238     SAOOffset& offsetParam = recParam[component];
00239 
00240     if(offsetParam.modeIdc == SAO_MODE_OFF)
00241     {
00242       continue;
00243     }
00244 
00245     switch(offsetParam.modeIdc)
00246     {
00247     case SAO_MODE_NEW:
00248       {
00249         invertQuantOffsets(component, offsetParam.typeIdc, offsetParam.typeAuxInfo, offsetParam.offset, offsetParam.offset);
00250       }
00251       break;
00252     case SAO_MODE_MERGE:
00253       {
00254         SAOBlkParam* mergeTarget = mergeList[offsetParam.typeIdc];
00255         CHECK(mergeTarget == NULL, "Merge target does not exist");
00256 
00257         offsetParam = (*mergeTarget)[component];
00258       }
00259       break;
00260     default:
00261       {
00262         THROW("Not a supported mode");
00263       }
00264     }
00265   }
00266 }
00267 
00268 void SampleAdaptiveOffset::xReconstructBlkSAOParams(CodingStructure& cs, SAOBlkParam* saoBlkParams)
00269 {
00270   for(uint32_t compIdx = 0; compIdx < MAX_NUM_COMPONENT; compIdx++)
00271   {
00272     m_picSAOEnabled[compIdx] = false;
00273   }
00274 
00275   const uint32_t numberOfComponents = getNumberValidComponents(cs.pcv->chrFormat);
00276 
00277   for(int ctuRsAddr=0; ctuRsAddr< cs.pcv->sizeInCtus; ctuRsAddr++)
00278   {
00279     SAOBlkParam* mergeList[NUM_SAO_MERGE_TYPES] = { NULL };
00280     getMergeList(cs, ctuRsAddr, saoBlkParams, mergeList);
00281 
00282     reconstructBlkSAOParam(saoBlkParams[ctuRsAddr], mergeList);
00283 
00284     for(uint32_t compIdx = 0; compIdx < numberOfComponents; compIdx++)
00285     {
00286       if(saoBlkParams[ctuRsAddr][compIdx].modeIdc != SAO_MODE_OFF)
00287       {
00288         m_picSAOEnabled[compIdx] = true;
00289       }
00290     }
00291   }
00292 }
