00295 void SampleAdaptiveOffset::offsetBlock(const int channelBitDepth, const ClpRng& clpRng, int typeIdx, int* offset
00296                                           , const Pel* srcBlk, Pel* resBlk, int srcStride, int resStride,  int width, int height
00297                                           , bool isLeftAvail,  bool isRightAvail, bool isAboveAvail, bool isBelowAvail, bool isAboveLeftAvail, bool isAboveRightAvail, bool isBelowLeftAvail, bool isBelowRightAvail
00298                                           , bool isCtuCrossedByVirtualBoundaries, int horVirBndryPos[], int verVirBndryPos[], int numHorVirBndry, int numVerVirBndry
00299   )
00300 {
00301   int x,y, startX, startY, endX, endY, edgeType;
00302   int firstLineStartX, firstLineEndX, lastLineStartX, lastLineEndX;
00303   int8_t signLeft, signRight, signDown;
00304 
00305   const Pel* srcLine = srcBlk;
00306         Pel* resLine = resBlk;
00307 
00308   switch(typeIdx)
00309   {
00310   case SAO_TYPE_EO_0:
00311     {
00312       offset += 2;
00313       startX = isLeftAvail ? 0 : 1;
00314       endX   = isRightAvail ? width : (width -1);
00315       for (y=0; y< height; y++)
00316       {
00317         signLeft = (int8_t)sgn(srcLine[startX] - srcLine[startX-1]);
00318         for (x=startX; x< endX; x++)
00319         {
00320           signRight = (int8_t)sgn(srcLine[x] - srcLine[x+1]);
00321           if (isCtuCrossedByVirtualBoundaries && isProcessDisabled(x, y, numVerVirBndry, 0, verVirBndryPos, horVirBndryPos))
00322           {
00323             signLeft = -signRight;
00324             continue;
00325           }
00326           edgeType =  signRight + signLeft;
00327           signLeft  = -signRight;
00328 
00329           resLine[x] = ClipPel<int>( srcLine[x] + offset[edgeType], clpRng);
00330         }
00331         srcLine  += srcStride;
00332         resLine += resStride;
00333       }
00334 
00335     }
00336     break;
00337   case SAO_TYPE_EO_90:
00338     {
00339       offset += 2;
00340       int8_t *signUpLine = &m_signLineBuf1[0];
00341 
00342       startY = isAboveAvail ? 0 : 1;
00343       endY   = isBelowAvail ? height : height-1;
00344       if (!isAboveAvail)
00345       {
00346         srcLine += srcStride;
00347         resLine += resStride;
00348       }
00349 
00350       const Pel* srcLineAbove= srcLine- srcStride;
00351       for (x=0; x< width; x++)
00352       {
00353         signUpLine[x] = (int8_t)sgn(srcLine[x] - srcLineAbove[x]);
00354       }
00355 
00356       const Pel* srcLineBelow;
00357       for (y=startY; y<endY; y++)
00358       {
00359         srcLineBelow= srcLine+ srcStride;
00360 
00361         for (x=0; x< width; x++)
00362         {
00363           signDown  = (int8_t)sgn(srcLine[x] - srcLineBelow[x]);
00364           if (isCtuCrossedByVirtualBoundaries && isProcessDisabled(x, y, 0, numHorVirBndry, verVirBndryPos, horVirBndryPos))
00365           {
00366             signUpLine[x] = -signDown;
00367             continue;
00368           }
00369           edgeType = signDown + signUpLine[x];
00370           signUpLine[x]= -signDown;
00371 
00372           resLine[x] = ClipPel<int>(srcLine[x] + offset[edgeType], clpRng);
00373         }
00374         srcLine += srcStride;
00375         resLine += resStride;
00376       }
00377 
00378     }
00379     break;
00380   case SAO_TYPE_EO_135:
00381     {
00382       offset += 2;
00383       int8_t *signUpLine, *signDownLine, *signTmpLine;
00384 
00385       signUpLine  = &m_signLineBuf1[0];
00386       signDownLine= &m_signLineBuf2[0];
00387 
00388       startX = isLeftAvail ? 0 : 1 ;
00389       endX   = isRightAvail ? width : (width-1);
00390 
00391       //prepare 2nd line's upper sign
00392       const Pel* srcLineBelow= srcLine+ srcStride;
00393       for (x=startX; x< endX+1; x++)
00394       {
00395         signUpLine[x] = (int8_t)sgn(srcLineBelow[x] - srcLine[x- 1]);
00396       }
00397 
00398       //1st line
00399       const Pel* srcLineAbove= srcLine- srcStride;
00400       firstLineStartX = isAboveLeftAvail ? 0 : 1;
00401       firstLineEndX   = isAboveAvail? endX: 1;
00402       for(x= firstLineStartX; x< firstLineEndX; x++)
00403       {
00404         if (isCtuCrossedByVirtualBoundaries && isProcessDisabled(x, 0, numVerVirBndry, numHorVirBndry, verVirBndryPos, horVirBndryPos))
00405         {
00406           continue;
00407         }
00408         edgeType  =  sgn(srcLine[x] - srcLineAbove[x- 1]) - signUpLine[x+1];
00409 
00410         resLine[x] = ClipPel<int>( srcLine[x] + offset[edgeType], clpRng);
00411       }
00412       srcLine  += srcStride;
00413       resLine  += resStride;
00414 
00415 
00416       //middle lines
00417       for (y= 1; y< height-1; y++)
00418       {
00419         srcLineBelow= srcLine+ srcStride;
00420 
00421         for (x=startX; x<endX; x++)
00422         {
00423           signDown =  (int8_t)sgn(srcLine[x] - srcLineBelow[x+ 1]);
00424           if (isCtuCrossedByVirtualBoundaries && isProcessDisabled(x, y, numVerVirBndry, numHorVirBndry, verVirBndryPos, horVirBndryPos))
00425           {
00426             signDownLine[x + 1] = -signDown;
00427             continue;
00428           }
00429           edgeType =  signDown + signUpLine[x];
00430           resLine[x] = ClipPel<int>( srcLine[x] + offset[edgeType], clpRng);
00431 
00432           signDownLine[x+1] = -signDown;
00433         }
00434         signDownLine[startX] = (int8_t)sgn(srcLineBelow[startX] - srcLine[startX-1]);
00435 
00436         signTmpLine  = signUpLine;
00437         signUpLine   = signDownLine;
00438         signDownLine = signTmpLine;
00439 
00440         srcLine += srcStride;
00441         resLine += resStride;
00442       }
00443 
00444       //last line
00445       srcLineBelow= srcLine+ srcStride;
00446       lastLineStartX = isBelowAvail ? startX : (width -1);
00447       lastLineEndX   = isBelowRightAvail ? width : (width -1);
00448       for(x= lastLineStartX; x< lastLineEndX; x++)
00449       {
00450         if (isCtuCrossedByVirtualBoundaries && isProcessDisabled(x, height - 1, numVerVirBndry, numHorVirBndry, verVirBndryPos, horVirBndryPos))
00451         {
00452           continue;
00453         }
00454         edgeType =  sgn(srcLine[x] - srcLineBelow[x+ 1]) + signUpLine[x];
00455         resLine[x] = ClipPel<int>( srcLine[x] + offset[edgeType], clpRng);
00456 
00457       }
00458     }
00459     break;
00460   case SAO_TYPE_EO_45:
00461     {
00462       offset += 2;
00463       int8_t *signUpLine = &m_signLineBuf1[1];
00464 
00465       startX = isLeftAvail ? 0 : 1;
00466       endX   = isRightAvail ? width : (width -1);
00467 
00468       //prepare 2nd line upper sign
00469       const Pel* srcLineBelow= srcLine+ srcStride;
00470       for (x=startX-1; x< endX; x++)
00471       {
00472         signUpLine[x] = (int8_t)sgn(srcLineBelow[x] - srcLine[x+1]);
00473       }
00474 
00475 
00476       //first line
00477       const Pel* srcLineAbove= srcLine- srcStride;
00478       firstLineStartX = isAboveAvail ? startX : (width -1 );
00479       firstLineEndX   = isAboveRightAvail ? width : (width-1);
00480       for(x= firstLineStartX; x< firstLineEndX; x++)
00481       {
00482         if (isCtuCrossedByVirtualBoundaries && isProcessDisabled(x, 0, numVerVirBndry, numHorVirBndry, verVirBndryPos, horVirBndryPos))
00483         {
00484           continue;
00485         }
00486         edgeType = sgn(srcLine[x] - srcLineAbove[x+1]) -signUpLine[x-1];
00487         resLine[x] = ClipPel<int>(srcLine[x] + offset[edgeType], clpRng);
00488       }
00489       srcLine += srcStride;
00490       resLine += resStride;
00491 
00492       //middle lines
00493       for (y= 1; y< height-1; y++)
00494       {
00495         srcLineBelow= srcLine+ srcStride;
00496 
00497         for(x= startX; x< endX; x++)
00498         {
00499           signDown =  (int8_t)sgn(srcLine[x] - srcLineBelow[x-1]);
00500           if (isCtuCrossedByVirtualBoundaries && isProcessDisabled(x, y, numVerVirBndry, numHorVirBndry, verVirBndryPos, horVirBndryPos))
00501           {
00502             signUpLine[x - 1] = -signDown;
00503             continue;
00504           }
00505           edgeType =  signDown + signUpLine[x];
00506           resLine[x] = ClipPel<int>(srcLine[x] + offset[edgeType], clpRng);
00507           signUpLine[x-1] = -signDown;
00508         }
00509         signUpLine[endX-1] = (int8_t)sgn(srcLineBelow[endX-1] - srcLine[endX]);
00510         srcLine  += srcStride;
00511         resLine += resStride;
00512       }
00513 
00514       //last line
00515       srcLineBelow= srcLine+ srcStride;
00516       lastLineStartX = isBelowLeftAvail ? 0 : 1;
00517       lastLineEndX   = isBelowAvail ? endX : 1;
00518       for(x= lastLineStartX; x< lastLineEndX; x++)
00519       {
00520         if (isCtuCrossedByVirtualBoundaries && isProcessDisabled(x, height - 1, numVerVirBndry, numHorVirBndry, verVirBndryPos, horVirBndryPos))
00521         {
00522           continue;
00523         }
00524         edgeType = sgn(srcLine[x] - srcLineBelow[x-1]) + signUpLine[x];
00525         resLine[x] = ClipPel<int>(srcLine[x] + offset[edgeType], clpRng);
00526 
00527       }
00528     }
00529     break;
00530   case SAO_TYPE_BO:
00531     {
00532       const int shiftBits = channelBitDepth - NUM_SAO_BO_CLASSES_LOG2;
00533       for (y=0; y< height; y++)
00534       {
00535         for (x=0; x< width; x++)
00536         {
00537           resLine[x] = ClipPel<int>(srcLine[x] + offset[srcLine[x] >> shiftBits], clpRng );
00538         }
00539         srcLine += srcStride;
00540         resLine += resStride;
00541       }
00542     }
00543     break;
00544   default:
00545     {
00546       THROW("Not a supported SAO types\n");
00547     }
00548   }
00549 }
00550 
00551 void SampleAdaptiveOffset::offsetCTU( const UnitArea& area, const CPelUnitBuf& src, PelUnitBuf& res, SAOBlkParam& saoblkParam, CodingStructure& cs)
00552 {
00553   const uint32_t numberOfComponents = getNumberValidComponents( area.chromaFormat );
00554   bool bAllOff=true;
00555   for( uint32_t compIdx = 0; compIdx < numberOfComponents; compIdx++)
00556   {
00557     if (saoblkParam[compIdx].modeIdc != SAO_MODE_OFF)
00558     {
00559       bAllOff=false;
00560     }
00561   }
00562   if (bAllOff)
00563   {
00564     return;
00565   }
00566 
00567   bool isLeftAvail, isRightAvail, isAboveAvail, isBelowAvail, isAboveLeftAvail, isAboveRightAvail, isBelowLeftAvail, isBelowRightAvail;
00568 
00569   //block boundary availability
00570   deriveLoopFilterBoundaryAvailibility(cs, area.Y(), isLeftAvail,isRightAvail,isAboveAvail,isBelowAvail,isAboveLeftAvail,isAboveRightAvail,isBelowLeftAvail,isBelowRightAvail);
00571 
00572   const size_t lineBufferSize = area.Y().width + 1;
00573   if (m_signLineBuf1.size() < lineBufferSize)
00574   {
00575     m_signLineBuf1.resize(lineBufferSize);
00576     m_signLineBuf2.resize(lineBufferSize);
00577   }
00578 
00579   int numHorVirBndry = 0, numVerVirBndry = 0;
00580   int horVirBndryPos[] = { -1,-1,-1 };
00581   int verVirBndryPos[] = { -1,-1,-1 };
00582   int horVirBndryPosComp[] = { -1,-1,-1 };
00583   int verVirBndryPosComp[] = { -1,-1,-1 };
00584   bool isCtuCrossedByVirtualBoundaries = isCrossedByVirtualBoundaries(area.Y().x, area.Y().y, area.Y().width, area.Y().height, numHorVirBndry, numVerVirBndry, horVirBndryPos, verVirBndryPos, cs.picHeader );
00585   for(int compIdx = 0; compIdx < numberOfComponents; compIdx++)
00586   {
00587     const ComponentID compID = ComponentID(compIdx);
00588     const CompArea& compArea = area.block(compID);
00589     SAOOffset& ctbOffset     = saoblkParam[compIdx];
00590 
00591     if(ctbOffset.modeIdc != SAO_MODE_OFF)
00592     {
00593       int  srcStride    = src.get(compID).stride;
00594       const Pel* srcBlk = src.get(compID).bufAt(compArea);
00595       int  resStride    = res.get(compID).stride;
00596       Pel* resBlk       = res.get(compID).bufAt(compArea);
00597       for (int i = 0; i < numHorVirBndry; i++)
00598       {
00599         horVirBndryPosComp[i] = (horVirBndryPos[i] >> vtm::getComponentScaleY(compID, area.chromaFormat)) - compArea.y;
00600       }
00601       for (int i = 0; i < numVerVirBndry; i++)
00602       {
00603         verVirBndryPosComp[i] = (verVirBndryPos[i] >> vtm::getComponentScaleX(compID, area.chromaFormat)) - compArea.x;
00604       }
00605 
00606       offsetBlock( cs.sps->getBitDepth(toChannelType(compID)),
00607                    cs.slice->clpRng(compID),
00608                    ctbOffset.typeIdc, ctbOffset.offset
00609                   , srcBlk, resBlk, srcStride, resStride, compArea.width, compArea.height
00610                   , isLeftAvail, isRightAvail
00611                   , isAboveAvail, isBelowAvail
00612                   , isAboveLeftAvail, isAboveRightAvail
00613                   , isBelowLeftAvail, isBelowRightAvail
00614                   , isCtuCrossedByVirtualBoundaries, horVirBndryPosComp, verVirBndryPosComp, numHorVirBndry, numVerVirBndry
00615                   );
00616     }
00617   } //compIdx
00618 }
00619 
00620 void SampleAdaptiveOffset::SAOProcess( CodingStructure& cs, SAOBlkParam* saoBlkParams
00621                                       )
00622 {
00623   CHECK(!saoBlkParams, "No parameters present");
00624 
00625   xReconstructBlkSAOParams(cs, saoBlkParams);
00626 
00627   const uint32_t numberOfComponents = getNumberValidComponents(cs.area.chromaFormat);
00628   bool bAllDisabled = true;
00629   for (uint32_t compIdx = 0; compIdx < numberOfComponents; compIdx++)
00630   {
00631     if (m_picSAOEnabled[compIdx])
00632     {
00633       bAllDisabled = false;
00634     }
00635   }
00636   if (bAllDisabled)
00637   {
00638     return;
00639   }
00640 
00641   const PreCalcValues& pcv = *cs.pcv;
00642   PelUnitBuf rec = cs.getRecoBuf();
00643   m_tempBuf.copyFrom( rec );
00644 
00645   int ctuRsAddr = 0;
00646   for( uint32_t yPos = 0; yPos < pcv.lumaHeight; yPos += pcv.maxCUHeight )
00647   {
00648     for( uint32_t xPos = 0; xPos < pcv.lumaWidth; xPos += pcv.maxCUWidth )
00649     {
00650       const uint32_t width  = (xPos + pcv.maxCUWidth  > pcv.lumaWidth)  ? (pcv.lumaWidth - xPos)  : pcv.maxCUWidth;
00651       const uint32_t height = (yPos + pcv.maxCUHeight > pcv.lumaHeight) ? (pcv.lumaHeight - yPos) : pcv.maxCUHeight;
00652       const UnitArea area( cs.area.chromaFormat, Area(xPos , yPos, width, height) );
00653 
00654       offsetCTU( area, m_tempBuf, rec, cs.picture->getSAO()[ctuRsAddr], cs);
00655       ctuRsAddr++;
00656     }
00657   }
00658 
00659   DTRACE_UPDATE(g_trace_ctx, (std::make_pair("poc", cs.slice->getPOC())));
00660   DTRACE_PIC_COMP(D_REC_CB_LUMA_SAO, cs, cs.getRecoBuf(), COMPONENT_Y);
00661   DTRACE_PIC_COMP(D_REC_CB_CHROMA_SAO, cs, cs.getRecoBuf(), COMPONENT_Cb);
00662   DTRACE_PIC_COMP(D_REC_CB_CHROMA_SAO, cs, cs.getRecoBuf(), COMPONENT_Cr);
00663 
00664   DTRACE    ( g_trace_ctx, D_CRC, "SAO" );
00665   DTRACE_CRC( g_trace_ctx, D_CRC, cs, cs.getRecoBuf() );
00666 
00667 }
