00669 
00670 void SampleAdaptiveOffset::deriveLoopFilterBoundaryAvailibility(CodingStructure& cs, const Position &pos,
00671   bool& isLeftAvail,
00672   bool& isRightAvail,
00673   bool& isAboveAvail,
00674   bool& isBelowAvail,
00675   bool& isAboveLeftAvail,
00676   bool& isAboveRightAvail,
00677   bool& isBelowLeftAvail,
00678   bool& isBelowRightAvail
00679   ) const
00680 {
00681   const int width = cs.pcv->maxCUWidth;
00682   const int height = cs.pcv->maxCUHeight;
00683   const CodingUnit* cuCurr = cs.getCU(pos, CH_L);
00684   const CodingUnit* cuLeft = cs.getCU(pos.offset(-width, 0), CH_L);
00685   const CodingUnit* cuRight = cs.getCU(pos.offset(width, 0), CH_L);
00686   const CodingUnit* cuAbove = cs.getCU(pos.offset(0, -height), CH_L);
00687   const CodingUnit* cuBelow = cs.getCU(pos.offset(0, height), CH_L);
00688   const CodingUnit* cuAboveLeft = cs.getCU(pos.offset(-width, -height), CH_L);
00689   const CodingUnit* cuAboveRight = cs.getCU(pos.offset(width, -height), CH_L);
00690   const CodingUnit* cuBelowLeft = cs.getCU(pos.offset(-width, height), CH_L);
00691   const CodingUnit* cuBelowRight = cs.getCU(pos.offset(width, height), CH_L);
00692 
00693   // check cross slice flags
00694   const bool isLoopFilterAcrossSlicePPS = cs.pps->getLoopFilterAcrossSlicesEnabledFlag();
00695   if (!isLoopFilterAcrossSlicePPS)
00696   {
00697     isLeftAvail       = (cuLeft == NULL)       ? false : CU::isSameSlice(*cuCurr, *cuLeft);
00698     isAboveAvail      = (cuAbove == NULL)      ? false : CU::isSameSlice(*cuCurr, *cuAbove);
00699     isRightAvail      = (cuRight == NULL)      ? false : CU::isSameSlice(*cuCurr, *cuRight);
00700     isBelowAvail      = (cuBelow == NULL)      ? false : CU::isSameSlice(*cuCurr, *cuBelow);
00701     isAboveLeftAvail  = (cuAboveLeft == NULL)  ? false : CU::isSameSlice(*cuCurr, *cuAboveLeft);
00702     isAboveRightAvail = (cuAboveRight == NULL) ? false : CU::isSameSlice(*cuCurr, *cuAboveRight);
00703     isBelowLeftAvail  = (cuBelowLeft == NULL)  ? false : CU::isSameSlice(*cuCurr, *cuBelowLeft);
00704     isBelowRightAvail = (cuBelowRight == NULL) ? false : CU::isSameSlice(*cuCurr, *cuBelowRight);
00705   }
00706   else
00707   {
00708     isLeftAvail       = (cuLeft != NULL);
00709     isAboveAvail      = (cuAbove != NULL);
00710     isRightAvail      = (cuRight != NULL);
00711     isBelowAvail      = (cuBelow != NULL);
00712     isAboveLeftAvail  = (cuAboveLeft != NULL);
00713     isAboveRightAvail = (cuAboveRight != NULL);
00714     isBelowLeftAvail  = (cuBelowLeft != NULL);
00715     isBelowRightAvail = (cuBelowRight != NULL);
00716   }
00717 
00718   // check cross tile flags
00719   const bool isLoopFilterAcrossTilePPS = cs.pps->getLoopFilterAcrossTilesEnabledFlag();
00720   if (!isLoopFilterAcrossTilePPS)
00721   {
00722     isLeftAvail       = (!isLeftAvail)       ? false : CU::isSameTile(*cuCurr, *cuLeft);
00723     isAboveAvail      = (!isAboveAvail)      ? false : CU::isSameTile(*cuCurr, *cuAbove);
00724     isRightAvail      = (!isRightAvail)      ? false : CU::isSameTile(*cuCurr, *cuRight);
00725     isBelowAvail      = (!isBelowAvail)      ? false : CU::isSameTile(*cuCurr, *cuBelow);
00726     isAboveLeftAvail  = (!isAboveLeftAvail)  ? false : CU::isSameTile(*cuCurr, *cuAboveLeft);
00727     isAboveRightAvail = (!isAboveRightAvail) ? false : CU::isSameTile(*cuCurr, *cuAboveRight);
00728     isBelowLeftAvail  = (!isBelowLeftAvail)  ? false : CU::isSameTile(*cuCurr, *cuBelowLeft);
00729     isBelowRightAvail = (!isBelowRightAvail) ? false : CU::isSameTile(*cuCurr, *cuBelowRight);
00730   }
00731 
00732   // check cross subpic flags
00733   const SubPic& curSubPic = cs.pps->getSubPicFromCU(*cuCurr);
00734   if (!curSubPic.getloopFilterAcrossEnabledFlag())
00735   {
00736     isLeftAvail       = (!isLeftAvail)       ? false : CU::isSameSubPic(*cuCurr, *cuLeft);
00737     isAboveAvail      = (!isAboveAvail)      ? false : CU::isSameSubPic(*cuCurr, *cuAbove);
00738     isRightAvail      = (!isRightAvail)      ? false : CU::isSameSubPic(*cuCurr, *cuRight);
00739     isBelowAvail      = (!isBelowAvail)      ? false : CU::isSameSubPic(*cuCurr, *cuBelow);
00740     isAboveLeftAvail  = (!isAboveLeftAvail)  ? false : CU::isSameSubPic(*cuCurr, *cuAboveLeft);
00741     isAboveRightAvail = (!isAboveRightAvail) ? false : CU::isSameSubPic(*cuCurr, *cuAboveRight);
00742     isBelowLeftAvail  = (!isBelowLeftAvail)  ? false : CU::isSameSubPic(*cuCurr, *cuBelowLeft);
00743     isBelowRightAvail = (!isBelowRightAvail) ? false : CU::isSameSubPic(*cuCurr, *cuBelowRight);
00744   }
00745 }
00746 
00747 bool SampleAdaptiveOffset::isCrossedByVirtualBoundaries(const int xPos, const int yPos, const int width, const int height, int& numHorVirBndry, int& numVerVirBndry, int horVirBndryPos[], int verVirBndryPos[], const PicHeader* picHeader )
00748 {
00749   numHorVirBndry = 0; numVerVirBndry = 0;
00750   if( picHeader->getVirtualBoundariesPresentFlag() )
00751   {
00752     for (int i = 0; i < picHeader->getNumHorVirtualBoundaries(); i++)
00753     {
00754      if (yPos <= picHeader->getVirtualBoundariesPosY(i) && picHeader->getVirtualBoundariesPosY(i) <= yPos + height)
00755       {
00756         horVirBndryPos[numHorVirBndry++] = picHeader->getVirtualBoundariesPosY(i);
00757       }
00758     }
00759     for (int i = 0; i < picHeader->getNumVerVirtualBoundaries(); i++)
00760     {
00761       if (xPos <= picHeader->getVirtualBoundariesPosX(i) && picHeader->getVirtualBoundariesPosX(i) <= xPos + width)
00762       {
00763         verVirBndryPos[numVerVirBndry++] = picHeader->getVirtualBoundariesPosX(i);
00764       }
00765     }
00766   }
00767   return numHorVirBndry > 0 || numVerVirBndry > 0 ;
00768 }
